correctedCode:
public class Parser {
    public static void main(String[] args) {
        String[] values = {"10", "20", "abc"};
        int total = 0;
        for (String v : values) {
            try {
                total += Integer.parseInt(v);
            } catch (NumberFormatException e) {
                System.out.println("Skipping invalid value: " + v);
            }
        }
        System.out.println(total);
    }
}
